def _frozen_fixture():
    raw = zlib.decompress(base64.b85decode(''.join(_BUNDLE)))
    assert hashlib.sha256(raw).hexdigest() == FIXTURE_SHA256
    extra = json.loads(raw)
    value = lobby_fixture()
    pause = json.loads(extra['pause_raw'])
    packets = sorted(value['rows'] + extra['packets'], key=lambda row: row['time'])
    events = sorted(value['events'] + extra['events'], key=lambda row: row['time'])
    since, audit = value['F']['started_at'], pause['failed_history']['audit_until']
    captured_packets = deepcopy([row for row in packets if since <= row['time'] <= audit])
    captured_events = deepcopy([row for row in events if since <= row['time'] <= audit])
    # The source pause is projected onto this compact portable journal. Its
    # saved state and boundary times remain the actual receipt values.
    pause['failed_history'] = history.failed_history(captured_packets, captured_events,
        value['ready'], value['F'], audit)
    serialized = json.dumps(pause['failed_history'], sort_keys=True, separators=(',', ':'), allow_nan=False)
    assert hashlib.sha256(serialized.encode()).hexdigest() == EXPECTED_HISTORY_SHA256
    return {'packets': packets, 'events': events, 'ready': value['ready'], 'failed': value['F'],
        'pause': pause, 'capture_packets': captured_packets, 'capture_events': captured_events}


def fixture():
    return deepcopy(_frozen_fixture())


def validate(value):
    return journals.validate_journals(*(value[k] for k in
        ('packets', 'events', 'ready', 'failed', 'pause', 'capture_packets', 'capture_events')))


def _event(value, name):
    return next(row for row in value['events'] if row.get('event') == name and
        row.get('session') == value['ready']['native_session'] and
        row['time'] > value['pause']['failed_history']['audit_until'])


def test_complete_ready_to_pause_journal_reconciles_archived_failed_window_without_io(monkeypatch):
    value = fixture()
    before = deepcopy(value)
    def forbidden(*args, **kwargs):
        raise AssertionError('journal proof attempted filesystem, process or client access')
    with monkeypatch.context() as blocked:
        for name in ('read_bytes', 'read_text', 'open', 'stat', 'is_file', 'is_dir', 'is_symlink', 'resolve'):
            blocked.setattr(Path, name, forbidden)
        for name in ('check_output', 'run', 'Popen'):
            blocked.setattr(subprocess, name, forbidden)
        for name in ('open', 'stat', 'lstat'):
            blocked.setattr(os, name, forbidden)
        blocked.setattr(builtins, 'open', forbidden)
        proof = validate(value)
        repeated = validate(value)
    assert value == before
    assert proof['schema'] == 'client442_bag_swap_failed_journals_v1'
    assert proof['failed_history'] == value['pause']['failed_history']
    assert proof['interval'] == {'since': value['ready']['started_at'],
        'until': value['pause']['finished_at'], 'audit_until': value['pause']['failed_history']['audit_until']}
    boundaries = proof['post_stop_boundaries']
    assert boundaries['stop_window'] == {'since': 1791425758.0443668, 'until': 1791425778.141195}
    assert boundaries['events'] == [_event(value, 'world_connection_closed'), _event(value, 'native_stream_closed')]
    assert len(boundaries['ordinary_latency_events']) == 4
    assert [row['time'] for row in boundaries['ordinary_latency_events']] == [1791425761.2841034, 1791425761.2842355, 1791425761.284297, 1791425761.285034]
    serialized = json.dumps(proof, sort_keys=True, separators=(',', ':'), allow_nan=False)
    assert json.loads(serialized) == proof
    assert serialized == json.dumps(repeated, sort_keys=True, separators=(',', ':'), allow_nan=False)


@pytest.mark.parametrize('fault', [
    'archive_packet_missing', 'archive_event_missing', 'archive_packet_extra', 'archive_event_extra',
    'archive_body_changed', 'archive_time_changed', 'history_digest_changed', 'old_cutoff_changed',
    'global_packet_not_dict', 'global_event_not_dict', 'global_packet_missing_time', 'global_event_missing_time',
    'global_packet_nan', 'global_event_nan', 'capture_packet_missing_time', 'capture_event_missing_time',
    'capture_packet_nan', 'capture_event_nan', 'foreign_login', 'foreign_creation',
    'extra_swap', 'extra_afk_metadata', 'extra_housekeeping_stand', 'item_removed',
    'missing_teardown', 'foreign_teardown', 'early_teardown', 'late_teardown', 'fake_teardown_error',
    'additional_teardown', 'unmatched_stop_ping', 'pre_entry_movement',
    'missing_prep_quartet', 'missing_tail_quartet', 'false_shutdown_check', 'missing_shutdown_check',
    'extra_shutdown_check', 'after_item_field15_changed', 'pause_qualified', 'pause_input_sent',
    'pause_operations_admitted', 'teardown_body_extra', 'invented_display_event',
    'packet_before_ready', 'packet_after_pause', 'event_before_ready', 'event_after_pause'])
def test_complete_journal_rejects_archive_drift_unattributed_rows_or_fake_teardown(fault):
    value = fixture()
    owner = value['ready']['native_session']
    cutoff = value['pause']['failed_history']['audit_until']
    timestamp = cutoff + 1
    if fault == 'archive_packet_missing': value['capture_packets'].pop()
    elif fault == 'archive_event_missing': value['capture_events'].pop()
    elif fault == 'archive_packet_extra': value['capture_packets'].append(deepcopy(value['capture_packets'][-1]))
    elif fault == 'archive_event_extra': value['capture_events'].append(deepcopy(value['capture_events'][-1]))
    elif fault == 'archive_body_changed': value['capture_packets'][-1]['body'] += '00'
    elif fault == 'archive_time_changed': value['capture_events'][-1]['time'] -= .001
    elif fault == 'history_digest_changed': value['pause']['failed_history']['source_packets_sha256'] = '0' * 64
    elif fault == 'old_cutoff_changed': value['pause']['failed_history']['audit_until'] -= 1
    elif fault in ('global_packet_not_dict', 'global_event_not_dict'):
        value['packets' if fault == 'global_packet_not_dict' else 'events'].append(None)
    elif fault in ('global_packet_missing_time', 'global_event_missing_time', 'global_packet_nan', 'global_event_nan',
            'capture_packet_missing_time', 'capture_event_missing_time', 'capture_packet_nan', 'capture_event_nan'):
        row = {'session': 'unrelated', 'name': 'IGNORED_FOREIGN_ROW'}
        field = ('capture_' if fault.startswith('capture') else '') + ('packets' if '_packet_' in fault else 'events')
        if fault.endswith('_nan'):
            for timestamp in (None, False, True, '1791425760', float('nan'), float('inf'), -float('inf')):
                changed = deepcopy(value)
                changed[field].append({**row, 'time': timestamp})
                with pytest.raises(RuntimeError):
                    validate(changed)
            return
        value[field].append(row)
    elif fault in ('foreign_login', 'foreign_creation'):
        value['events'].append({'session': 'new-foreign-instance', 'time': timestamp,
            **({'event': 'instance_authenticated', 'account_id': 2} if fault == 'foreign_login' else
               {'event': 'native_player_created', 'guid': 2, 'map': 0})})
    elif fault in ('extra_swap', 'extra_housekeeping_stand'):
        value['packets'].append({'session': owner, 'time': timestamp, 'direction': 'from_client',
            'name': 'CMSG_SWAP_INV_ITEM' if fault == 'extra_swap' else 'CMSG_STAND_STATE_CHANGE',
            'body': '0001' if fault == 'extra_swap' else '00'})
    elif fault == 'extra_afk_metadata':
        value['events'].append({'session': owner, 'time': timestamp, 'direction': 'from_client',
            'event': 'modern_packet', 'name': 'CMSG_CHAT_MESSAGE_AFK', 'bytes': 5})
    elif fault == 'item_removed':
        value['packets'].append(_removal((0x4000 << 48) | 41, owner, timestamp))
    elif fault == 'missing_teardown': value['events'].remove(_event(value, 'native_stream_closed'))
    elif fault in ('foreign_teardown', 'early_teardown', 'late_teardown', 'fake_teardown_error'):
        row = _event(value, 'native_stream_closed')
        if fault == 'foreign_teardown': row['session'] = 'unrelated'
        elif fault == 'early_teardown': row['time'] = cutoff - 1
        elif fault == 'late_teardown': row['time'] = value['pause']['stop_finished_at'] + 1
        else: row['error'] = 'invented clean shutdown'
    elif fault == 'additional_teardown':
        value['events'].append({**_event(value, 'world_connection_closed'), 'time': timestamp})
    elif fault == 'unmatched_stop_ping':
        value['events'].remove(next(row for row in value['events'] if row.get('name') == 'CMSG_PING' and
            row.get('direction') == 'from_client' and row['time'] > cutoff))
    elif fault in ('missing_prep_quartet', 'missing_tail_quartet'):
        value['events'] = [row for row in value['events'] if not
            (row['time'] < value['failed']['started_at'] if fault == 'missing_prep_quartet' else
             row['time'] > cutoff and row.get('name') in ('CMSG_PING', 'SMSG_PONG'))]
    elif fault in ('false_shutdown_check', 'missing_shutdown_check', 'extra_shutdown_check'):
        checks = value['pause']['shutdown_checks']
        if fault == 'false_shutdown_check': checks['owned_game_absent'] = False
        elif fault == 'missing_shutdown_check': del checks['owned_game_absent']
        else: checks['invented_cleanup_check'] = True
    elif fault == 'after_item_field15_changed':
        value['pause']['after']['2']['inventory'][0][14] += 1
    elif fault in ('pause_qualified', 'pause_input_sent', 'pause_operations_admitted'):
        key = {'pause_qualified': 'qualification_added', 'pause_input_sent': 'input_sent',
            'pause_operations_admitted': 'operations_admitted'}[fault]
        value['pause'][key] = 1 if fault == 'pause_operations_admitted' else True
    elif fault == 'teardown_body_extra': _event(value, 'native_stream_closed')['body'] = ''
    elif fault == 'invented_display_event':
        value['events'].append({'session': owner, 'time': timestamp, 'event': 'display_teardown',
            'actor': 'scout', 'display': ':2'})
    elif fault in ('packet_before_ready', 'packet_after_pause', 'event_before_ready', 'event_after_pause'):
        timestamp = (value['ready']['started_at'] - 1 if fault.endswith('before_ready') else
            value['pause']['finished_at'] + 1)
        row = {'session': 'unrelated-new-instance', 'time': timestamp, 'direction': 'from_client',
            'name': 'CMSG_PLAYER_LOGIN'}
        if fault.startswith('packet'):
            value['packets'].append({**row, 'body': '0200000000000000'})
        else:
            value['events'].append({**row, 'event': 'modern_packet', 'bytes': 8})
    elif fault == 'pre_entry_movement':
        value['events'].append({'session': owner, 'time': value['ready']['started_at'] + 1,
            'event': 'unmapped_client_packet', 'name': 'CMSG_MOVE_HEARTBEAT', 'bytes': 1})
    with pytest.raises(RuntimeError):
        validate(value)


@pytest.mark.parametrize('journal', ['packets', 'events'])
def test_complete_journal_preserves_the_original_pause_copy_order(journal):
    value = fixture()
    rows = value[journal]
    audit = value['pause']['failed_history']['audit_until']
    index = next(i for i in range(len(rows) - 1) if
        value['failed']['finished_at'] < rows[i]['time'] < rows[i + 1]['time'] <= audit and
        rows[i].get('name') in history.ROUTINE and rows[i + 1].get('name') in history.ROUTINE)
    previous_keys = sorted(history.key(row) for row in rows)
    rows[index], rows[index + 1] = rows[index + 1], rows[index]
    assert sorted(history.key(row) for row in rows) == previous_keys
    # These ordinary reads are semantically identical to the frozen history;
    # reconciliation must nevertheless preserve their recorded file order.
    replay = history.failed_history(value['packets'], value['events'], value['ready'], value['failed'], audit)
    assert replay == value['pause']['failed_history']
    with pytest.raises(RuntimeError, match='original pause journal rows.*reordered'):
        validate(value)
